--region public
---刷新页面
function GroceryClubNode:Refresh()
    self:InitData()
    self:InitUI()
    self:RefreshUI()
    self:PlayEnterAnimation()
end

---刷新货币栏
function GroceryClubNode:RefreshCurrencyBar()
    local currencyList = GroceryUtils.GetCurrencyByGroceryType(self:GetGroceryType())
    if not currencyList then
        currencyList = {Constants.Currency.FreeDiamondId}
    end
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---播放进入动画
function GroceryClubNode:PlayEnterAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreSynchronousPvpDialog_L")
end

---播放进入动画
function GroceryClubNode:PlaySwitchTabAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreSynchronousPvpDialog_T")
end

---刷新锁定状态
function GroceryClubNode:RefreshLockState()
    local selectedTab = self:GetSelectedTab()
    if GameUtils.IsUnlockedBySystemTogId(self:GetTopTabUnlockIdByIndex(selectedTab)) then
        CfUtils.SetActive(self.Lock, false)
    else
        CfUtils.SetActive(self.Lock, true)
        CfUtils.FillText(self.LockTextDesc, GameUtils.GetUnlockDescrBySystemTogId(self:GetTopTabUnlockIdByIndex(selectedTab)))
    end
end

---更新顶部页签UI
function GroceryClubNode:UpdateTopTabUI()
    local posX = self.Content.localPosition.x
    local viewportW = self.Viewport.rect.width
    local contentW = self.Content.rect.width
    CfUtils.SetActive(self.Left, posX < -0.1)
    CfUtils.SetActive(self.Right, contentW - viewportW + posX> 0)
end
--endregion private

